import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import {
  KozmosDensityScope,
  KozmosLink,
  KozmosStack,
  KozmosText,
  KozmosThemeProvider,
} from "../../index";

/**
 * Vue's Link: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port Link`; ExternalInText and ExternalRightToLeft
 * written by hand, with the native Text and Stack.
 */
type Args = Record<string, unknown>;
const SLOTS = ["children"];

const meta: Meta<Args> = {
  title: "Vue/Core/Actions/Link",
  component: KozmosLink,
  // React's node props are Vue's slots: `children` the default slot, the
  // rest slots of their own names, each drawing its arg's text.
  render: (args) => ({
    setup: () => () => {
      const props: Args = {};
      const slots: Record<string, () => string> = {};
      for (const [key, value] of Object.entries(args)) {
        if (!SLOTS.includes(key)) props[key] = value;
        else if (value !== undefined && value !== null)
          slots[key === "children" ? "default" : key] = () => String(value);
      }
      return h(KozmosLink, props, slots);
    },
  }),
};

export default meta;
type Story = StoryObj<Args>;

export const Default: Story = {
  args: {
    children: "Default Link",
    href: "#",
    variant: "default",
  },
};

export const Subtle: Story = {
  args: {
    children: "Subtle Link",
    href: "#",
    variant: "subtle",
  },
};

export const External: Story = {
  args: {
    children: "Privacy Policy",
    href: "https://example.com/privacy",
    external: true,
  },
};

/**
 * In running text, in a column narrow enough to wrap: the icon stays with
 * the link's last word, in touch density and compact, default and subtle.
 */
export const ExternalInText: Story = {
  // Drawn by a render function, word for word as React's JSX: each of
  // React's text nodes is one here, which a template's whitespace is not.
  render: () => ({
    setup: () => () => {
      const paragraph = () =>
        h(KozmosText, { size: "sm", style: { width: "208px" } }, () => [
          "Read our",
          " ",
          h(
            KozmosLink,
            { href: "https://example.com/privacy", external: true },
            () => "Privacy Policy",
          ),
          " ",
          "and the",
          " ",
          h(
            KozmosLink,
            {
              href: "https://example.com/terms",
              external: true,
              variant: "subtle",
            },
            () => "Terms of Service",
          ),
          " ",
          "before you continue.",
        ]);
      return h(KozmosStack, { direction: "row", gap: 6 }, () => [
        paragraph(),
        h(KozmosDensityScope, { density: "compact" }, () => [paragraph()]),
      ]);
    },
  }),
};

/** Right to left, the icon sits at the link's end and points to it. */
export const ExternalRightToLeft: Story = {
  render: (_args, { globals }) => ({
    setup: () => () =>
      h(
        KozmosThemeProvider,
        {
          dir: "rtl",
          theme: globals?.theme === "dark" ? "dark" : "light",
          density: globals?.density === "compact" ? "compact" : "touch",
        },
        () => [
          h(KozmosText, { size: "sm", style: { width: "208px" } }, () => [
            "اقرأ",
            " ",
            h(
              KozmosLink,
              {
                href: "https://example.com/privacy",
                external: true,
                externalLabel: "يفتح في علامة تبويب جديدة",
              },
              () => "سياسة الخصوصية",
            ),
            " ",
            "قبل المتابعة.",
          ]),
        ],
      ),
  }),
};
